mapper.select:
select va.application_id, va.visitor_id, va.host_name, va.reason, va.start_time, va.end_time, va.status, va.approve_time, v.name as visitor_name, v.phone as visitor_phone, v.id_card as visitor_id_card, v.company as visitor_company, v.avatar as visitor_avatar, v.plate_no, (select count(1) from visitor_entry e1 where e1.application_id = va.application_id and e1.create_time >= #{dateStart} and e1.create_time < #{nextDayStart}) as entry_count, (select max(e2.create_time) from visitor_entry e2 where e2.application_id = va.application_id and e2.create_time >= #{dateStart} and e2.create_time < #{nextDayStart}) as last_entry_time from visitor_application va left join visitor v on va.visitor_id = v.visitor_id where va.status = '1' and va.del_flag = '0' and va.start_time < #{nextDayStart} and va.end_time >= #{dateStart}
and ( v.name like concat('%', #{keyword}, '%') or v.phone like concat('%', #{keyword}, '%') or v.id_card like concat('%', #{keyword}, '%') or v.plate_no like concat('%', #{keyword}, '%') )
order by va.create_time desc
